    98	    pub fn create(source: &'a [u8], tokens: &[XmlToken]) -> Result<Self, CssError> {
    99	        let mut sheet = Self { source, rules: Vec::new(), declaration_count: 0, css_bytes: 0,
   100	            match_tests: 0, selector_visits: 0, hit_limit: false };
   101	        for (index, token) in tokens.iter().enumerate() {
   102	            if token.kind != TokenKind::StartElement || !is_style_element(source, token) { continue; }
   103	            let mut cursor = index + 1;
   104	            while cursor < tokens.len() && tokens[cursor].kind != TokenKind::EndElement {
   105	                let child = &tokens[cursor];
   106	                if matches!(child.kind, TokenKind::Text | TokenKind::Cdata) {
   107	                    let bytes = checked_slice(source, child.value)?;
   108	                    sheet.css_bytes = sheet.css_bytes.checked_add(bytes.len()).ok_or(CssError::Limit)?;
   109	                    if sheet.css_bytes > MAX_BYTES { return Err(CssError::Limit); }
   110	                    sheet.parse_stylesheet(child.value.offset, child.value.offset + child.value.length)?;
   111	                }
   112	                cursor += 1;
   113	            }
   114	        }
   115	        Ok(sheet)
   116	    }
