   122	                       parent: Option<&CssPaint<'b>>) -> Result<CssPaint<'b>, CssError> {
   123	        let token = tokens.get(element).ok_or(CssError::Limit)?;
   124	        if !is_element(token) { return Err(CssError::Limit); }
   125	        let mut paint = parent.copied().unwrap_or_else(CssPaint::initial);
   126	        for property in [Property::ClipPath, Property::Filter, Property::Mask, Property::MixBlendMode,
   127	            Property::Isolation, Property::VectorEffect, Property::Opacity, Property::Display] {
   128	            paint.values[property as usize] = None;
   129	        }
   130	        let mut winners: [Option<Winner>; PROPERTY_COUNT] = [None; PROPERTY_COUNT];
   131	        let selector_visits = &mut self.selector_visits;
   132	        let hit_limit = &mut self.hit_limit;
   133	        for rule in &self.rules {
   134	            if self.match_tests >= MAX_RULE_MATCHES { self.hit_limit = true; return Err(CssError::Limit); }
   135	            self.match_tests += 1;
   136	            if matches_selector(source, &rule.selector, tokens, element, selector_visits, hit_limit)? {
   137	                if rule.unsupported && token.prefix.length == 0 && span_eq(source, token.local_name, b"stop") {
