   139	                }
   140	                for (i, declaration) in rule.declarations.iter().enumerate() {
   141	                    offer(&mut winners, *declaration, rule.selector.specificity,
   142	                          rule.order.saturating_mul(MAX_DECLARATIONS).saturating_add(i));
   143	                }
   144	            }
   145	        }
   146	        // Presentation attributes have zero specificity and precede stylesheet rules.
   147	        for property in Property::ALL {
   148	            if let Some(value) = attribute(source, tokens, element, property.name()) {
   149	                offer(&mut winners, Declaration { property, value, important: false }, 0, 0);
   150	            }
   151	        }
   152	        if let Some(style) = attribute(source, tokens, element, b"style") {
   153	            if style.length > MAX_BYTES { return Err(CssError::Limit); }
   154	            let mut inline = Vec::new();
   155	            let _ = parse_declarations(source, style, &mut inline, &mut self.hit_limit)?;
   156	            for (i, declaration) in inline.iter().enumerate() {
   157	                offer(&mut winners, *declaration, 1_000_000, i);
   158	            }
   159	        }
   160	        for property in Property::ALL {
   161	            if let Some(winner) = winners[property as usize] {
   162	                let value = checked_slice(source, winner.value)?;
   163	                if keyword(value, b"inherit") || (keyword(value, b"unset") && inherited(property)) {
   164	                    paint.values[property as usize] = parent.and_then(|p| p.value(property));
   165	                } else if keyword(value, b"initial") || keyword(value, b"unset") {
   166	                    paint.values[property as usize] = None;
   167	                } else {
   168	                    paint.values[property as usize] = Some(CssValue { span: winner.value, bytes: value });
   169	                }
   170	            }
   171	        }
   172	        Ok(paint)
   173	    }
