   175	    fn parse_stylesheet(&mut self, start: usize, end: usize) -> Result<(), CssError> {
   176	        let mut i = start;
   177	        while i < end {
   178	            skip_space_comments(self.source, &mut i, end);
   179	            if i >= end { break; }
   180	            if self.source[i] == b'@' {
   181	                i = skip_at_rule(self.source, i, end);
   182	                continue;
   183	            }
   184	            let selector_start = i;
   185	            let Some(brace) = find_unquoted(self.source, i, end, b'{') else { break };
   186	            let Some(close) = matching_brace(self.source, brace + 1, end) else { break };
   187	            let mut declarations = Vec::new();
   188	            let unsupported = parse_declarations(self.source, XmlSpan { offset: brace + 1, length: close - brace - 1 }, &mut declarations, &mut self.hit_limit)?;
   189	            let mut part = selector_start;
   190	            while part < brace {
   191	                let comma = find_unquoted(self.source, part, brace, b',').unwrap_or(brace);
   192	                if let Some(selector) = parse_selector(self.source, part, comma) {
   193	                    if !declarations.is_empty() || unsupported {
   194	                        let new_rules = self.rules.len().checked_add(1).ok_or(CssError::Limit)?;
   195	                        if new_rules > MAX_RULES || declarations.len() > MAX_DECLARATIONS.saturating_sub(self.declaration_count) {
   196	                            self.hit_limit = true; return Err(CssError::Limit);
   197	                        }
   198	                        self.rules.try_reserve(1).map_err(|_| CssError::OutOfMemory)?;
   199	                        let mut copy = Vec::new();
   200	                        copy.try_reserve_exact(declarations.len()).map_err(|_| CssError::OutOfMemory)?;
   201	                        copy.extend_from_slice(&declarations);
   202	                        self.declaration_count += copy.len();
   203	                        self.rules.push(Rule { selector, declarations: copy, order: self.rules.len(), unsupported });
   204	                    }
   205	                }
   206	                part = if comma < brace { comma + 1 } else { brace };
   207	            }
   208	            i = close + 1;
   209	        }
   210	        Ok(())
   211	    }
   212	}
