   216	fn offer(winners: &mut [Option<Winner>; PROPERTY_COUNT], declaration: Declaration, specificity: u32, order: usize) {
   217	    let slot = &mut winners[declaration.property as usize];
   218	    let wins = slot.is_none_or(|old| declaration.important > old.important ||
   219	        (declaration.important == old.important && (specificity > old.specificity ||
   220	        (specificity == old.specificity && order >= old.order))));
   221	    if wins { *slot = Some(Winner { value: declaration.value, important: declaration.important, specificity, order }); }
   222	}
