   310	fn parse_declarations(source: &[u8], span: XmlSpan, output: &mut Vec<Declaration>, hit_limit: &mut bool) -> Result<bool, CssError> {
   311	    let end = span.end().ok_or(CssError::Limit)?;
   312	    checked_slice(source, span)?;
   313	    let mut i = span.offset; let mut unsupported = false;
   314	    while i < end {
   315	        skip_space_comments(source, &mut i, end);
   316	        if i >= end { break; }
   317	        let start = i; let mut colon = None; let mut quote = 0; let mut parens = 0usize;
   318	        while i < end {
   319	            let c = source[i];
   320	            if quote != 0 { if c == b'\\' { i = (i + 2).min(end); continue; } if c == quote { quote = 0; } }
   321	            else if c == b'\'' || c == b'"' { quote = c; }
   322	            else if i + 1 < end && source[i..i + 2] == *b"/*" { i = comment_end(source, i, end); continue; }
   323	            else if c == b'(' { parens = parens.saturating_add(1); }
   324	            else if c == b')' { parens = parens.saturating_sub(1); }
   325	            else if c == b':' && colon.is_none() { colon = Some(i); }
   326	            else if c == b';' && parens == 0 { break; }
   327	            i += 1;
   328	        }
   329	        let segment_end = i;
   330	        if i < end { i += 1; }
   331	        let Some(colon) = colon.filter(|c| *c < segment_end) else { continue };
   332	        let mut ns = start; let mut ne = colon;
   333	        while ns < ne && is_space(source[ns]) { ns += 1; }
   334	        while ne > ns && is_space(source[ne - 1]) { ne -= 1; }
   335	        let mut vs = colon + 1; let mut ve = segment_end;
   336	        trim_value(source, &mut vs, &mut ve);
   337	        if ns == ne || vs == ve { continue; }
   338	        let name = &source[ns..ne];
   339	        let Some(property) = Property::ALL.iter().copied().find(|p| name.eq_ignore_ascii_case(p.name())) else { unsupported = true; continue };
   340	        let (value_end, important) = strip_important(source, vs, ve);
   341	        ve = value_end;
   342	        if ve <= vs { continue; }
   343	        if output.len() >= MAX_DECLARATIONS { *hit_limit = true; return Err(CssError::Limit); }
   344	        output.try_reserve(1).map_err(|_| CssError::OutOfMemory)?;
   345	        output.push(Declaration { property, value: XmlSpan { offset: vs, length: ve - vs }, important });
   346	    }
   347	    Ok(unsupported)
   348	}
   349	fn trim_value(source: &[u8], start: &mut usize, end: &mut usize) {
   350	    loop { while *start < *end && is_space(source[*start]) { *start += 1; }
   351	        if *start + 1 < *end && source[*start..*start + 2] == *b"/*" { *start = comment_end(source, *start, *end); } else { break; } }
