   370	    while i < end {
   371	        let c = source[i];
   372	        if quote != 0 {
   373	            if c == b'\\' { i = (i + 2).min(end); continue; }
   374	            if c == quote { quote = 0; }
   375	        } else if c == b'\'' || c == b'"' { quote = c; }
