   382	fn parse_selector(source: &[u8], mut start: usize, mut end: usize) -> Option<Selector> {
   383	    while end > start && is_space(source[end - 1]) { end -= 1; }
   384	    while start < end && is_space(source[start]) { start += 1; }
   385	    let mut result = Selector::EMPTY; let mut i = start;
   386	    while i < end {
   387	        if result.count == MAX_SELECTOR_TERMS { return None; }
   388	        let mut term = Term::EMPTY;
   389	        if source[i] != b'#' && source[i] != b'.' {
   390	            let begin = i; while i < end && ident(source[i]) { i += 1; }
   391	            if begin == i { return None; }
