   404	        result.terms[result.count] = term; result.count += 1;
   405	        let before = i; while i < end && is_space(source[i]) { i += 1; }
   406	        if i < end && (i == before || matches!(source[i], b'>' | b'+' | b'~')) { return None; }
   407	    }
   408	    (result.count > 0).then_some(result)
