   411	fn matches_selector(source: &[u8], selector: &Selector, tokens: &[XmlToken], element: usize,
   412	                    selector_visits: &mut usize, hit_limit: &mut bool) -> Result<bool, CssError> {
   413	    if selector.count == 0 || !matches_term(source, &selector.terms[selector.count - 1], tokens, element) { return Ok(false); }
   414	    let mut descendant = element;
   415	    for term in (0..selector.count - 1).rev() {
   416	        let depth = tokens[descendant].depth; let mut found = None;
   417	        for candidate in (0..descendant).rev() {
   418	            if !is_element(&tokens[candidate]) || tokens[candidate].depth >= depth { continue; }
   419	            if *selector_visits >= MAX_RULE_MATCHES { *hit_limit = true; return Err(CssError::Limit); }
   420	            *selector_visits += 1;
   421	            if matches_term(source, &selector.terms[term], tokens, candidate) { found = Some(candidate); break; }
   422	        }
   423	        let Some(parent) = found else { return Ok(false) }; descendant = parent;
   424	    }
   425	    Ok(true)
   426	}
   427	fn matches_term(source: &[u8], term: &Term, tokens: &[XmlToken], element: usize) -> bool {
